import { ReactNode, FC } from 'react';

interface CollapseProps {
    /** 当前展开项的 key (受控) */
    activeKey?: string | string[];
    /** 默认展开项 */
    defaultActiveKey?: string | string[];
    /** 是否手风琴模式 (只展开一项) */
    accordion?: boolean;
    /** 展开变化回调 */
    onChange?: (activeKey: string | string[]) => void;
    /** 是否显示边框 */
    bordered?: boolean;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}
interface CollapsePanelProps {
    /** 唯一标识 */
    key: string;
    /** 面板标题 */
    title: ReactNode;
    /** 额外内容 (标题右侧) */
    extra?: ReactNode;
    /** 是否禁用 */
    disabled?: boolean;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

type CollapseComponent = FC<CollapseProps> & {
    Panel: FC<CollapsePanelProps>;
};
declare const Collapse: CollapseComponent;
interface CollapsePanelInternalProps extends CollapsePanelProps {
    __key?: string;
}
declare const CollapsePanel: FC<CollapsePanelInternalProps>;

export { Collapse, CollapsePanel, Collapse as default };
export type { CollapsePanelProps, CollapseProps };
